select
  id, owner_id, owner_id_card, building_id, build_name, shops_status, create_time, update_time, remark, area, floor
from sys_shops


        and id = #{id}


        and owner_id = #{ownerId}


        and owner_id_card = #{ownerIdCard}


        and building_id = #{buildingId}


        and build_name = #{buildName}


        and shops_status = #{shopsStatus}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and remark = #{remark}


        and area = #{area}


        and floor = #{floor}


limit #{pageable.offset}, #{pageable.pageSize}

